def verify_evolution_checkpoint_bundle(report: Any, expected: Any) -> bool:
    if not isinstance(report, dict) or set(report) != set(_EVOLUTION_CHECKPOINT_BUNDLE_REPORT_KEYS):
        raise ValueError("report must be a dict with exactly the keys root, proofs")
    report_root = _check_hex64(report["root"], "report.root")
    raw_members = report["proofs"]
    if not isinstance(raw_members, list) or not raw_members:
        raise ValueError("report.proofs must be a non-empty list")
    members = []
    seen_ids = set()
    previous_id = None
    for index, member in enumerate(raw_members):
        field = f"report.proofs[{index}]"
        if not isinstance(member, dict) or set(member) != set(_EVOLUTION_CHECKPOINT_BUNDLE_MEMBER_KEYS):
            raise ValueError(f"{field} must be a dict with exactly the keys id, proof, previous, digest")
        proof_id = _check_non_empty_str(member["id"], f"{field}.id")
        if proof_id in seen_ids:
            raise ValueError(f"report.proofs contains a duplicate id: {proof_id!r}")
        if previous_id is not None and not previous_id < proof_id:
            raise ValueError("report.proofs must be ordered by id in ascending Unicode code point order")
        previous = _check_hex64(member["previous"], f"{field}.previous")
        digest = _check_hex64(member["digest"], f"{field}.digest")
        proof = _canonical_evolution_checkpoint_proof(member["proof"], f"{field}.proof")
        members.append({"id": proof_id, "proof": proof, "previous": previous, "digest": digest})
        seen_ids.add(proof_id)
        previous_id = proof_id
    if not isinstance(expected, dict) or set(expected) != _EVOLUTION_CHECKPOINT_BUNDLE_EXPECTED_KEYS:
        raise ValueError("expected must be a dict with exactly the keys root, proof_ids")
    expected_root = _check_hex64(expected["root"], "expected.root")
    proof_ids = expected["proof_ids"]
    if not isinstance(proof_ids, list) or not proof_ids:
        raise ValueError("expected.proof_ids must be a non-empty list")
    expected_ids = set()
    for index, proof_id in enumerate(proof_ids):
        _check_non_empty_str(proof_id, f"expected.proof_ids[{index}]")
        if proof_id in expected_ids:
            raise ValueError("expected.proof_ids must not contain duplicates")
        expected_ids.add(proof_id)

    # Both inputs have now passed every structural and semantic check.
    if expected_ids != seen_ids:
        return False
    previous = _EVOLUTION_CHECKPOINT_BUNDLE_GENESIS
    for member in members:
        if not verify_evolution_checkpoint(member["proof"], _self_expected(member["proof"])):
            return False
        if member["previous"] != previous:
            return False
        recomputed = _evolution_checkpoint_bundle_member_digest(previous, member["id"], member["proof"])
        if member["digest"] != recomputed:
            return False
        previous = recomputed
    if report_root != previous or expected_root != report_root:
        return False
    return True
